import { useState, useEffect, useRef } from "react";

const STORAGE_KEY = "atelier_data_v3";
const initialData = { sessions: [], expenses: [], incomes: [], events: [] };

const FIRMA = {
  name:      "Surkow Art",
  kuenstler: "Paul Surkow",
  atelier:   "Privat Atelier Dreizehn",
  adresse:   "Federnseeplatz 13",
  plzOrt:    "72764 Reutlingen",
  web:       "www.surkow-art.de",
  email:     "info@surkow-art.de",
};

// ── Color palette from logo ──────────────────────────────────────────
const C = {
  purple:    "#7B2D8B",
  purpleDk:  "#4A1260",
  purpleMd:  "#9B3DAB",
  purpleLt:  "#C87FD8",
  purpleXlt: "#F2E6F6",
  cream:     "#FAF6FD",
  darkText:  "#2A1035",
  grey:      "#888",
  green:     "#2E7D32",
  red:       "#C0392B",
  gold:      "#C8A96E",
};

function loadData() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    return raw ? { ...initialData, ...JSON.parse(raw) } : initialData;
  } catch { return initialData; }
}
function saveData(d) { localStorage.setItem(STORAGE_KEY, JSON.stringify(d)); }

function formatDuration(ms) {
  const s = Math.floor(ms/1000), h = Math.floor(s/3600), m = Math.floor((s%3600)/60), sec = s%60;
  return `${String(h).padStart(2,"0")}:${String(m).padStart(2,"0")}:${String(sec).padStart(2,"0")}`;
}
function formatDate(iso) { return new Date(iso).toLocaleDateString("de-DE",{day:"2-digit",month:"2-digit",year:"numeric"}); }
function formatTime(iso) { return new Date(iso).toLocaleTimeString("de-DE",{hour:"2-digit",minute:"2-digit"}); }
function today() { return new Date().toISOString().split("T")[0]; }
function groupByMonth(items, key="start") {
  const map = {};
  items.forEach(i => {
    const d = new Date(i[key]);
    const k = `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}`;
    if (!map[k]) map[k] = [];
    map[k].push(i);
  });
  return map;
}
const MONTHS_LONG  = ["Januar","Februar","März","April","Mai","Juni","Juli","August","September","Oktober","November","Dezember"];
const MONTHS_SHORT = ["Jan","Feb","Mär","Apr","Mai","Jun","Jul","Aug","Sep","Okt","Nov","Dez"];
const DAYS_SHORT   = ["Mo","Di","Mi","Do","Fr","Sa","So"];
function monthLabel(key) { const [y,m]=key.split("-"); return `${MONTHS_SHORT[parseInt(m)-1]} ${y}`; }

const EXPENSE_CATS = ["Rahmen","Material","Medium","Ateliermiete","Prints","Werbung","Sonstiges"];
const INCOME_ARTS  = ["Original Gemälde","Print","Auftragsarbeit","Mehraufwand"];
const EVENT_TYPES  = ["Auftragsarbeit","Ausstellung","Messe","Vernissage","Workshop","Sonstiges"];

const inp = {
  width:"100%", border:`1px solid ${C.purpleLt}55`, borderRadius:6,
  padding:"10px 12px", fontFamily:"Georgia,serif", fontSize:13,
  color:C.darkText, background:"#fff", outline:"none", boxSizing:"border-box",
};
const mkBtn = (bg=C.purpleDk, color="#fff") => ({
  background:bg, color, border:"none", borderRadius:6,
  padding:"11px 20px", fontSize:13, letterSpacing:1.5,
  textTransform:"uppercase", cursor:"pointer", fontFamily:"Georgia,serif",
  transition:"opacity 0.2s",
});

// ── Invoice Modal ───────────────────────────────────────────────────────────────────────
function InvoiceModal({ items, onClose, events }) {
  const [customer, setCustomer] = useState({ name:"", address:"", city:"", email:"" });
  const [invoiceNr, setInvoiceNr] = useState(
    `RE-${new Date().getFullYear()}-${String(Math.floor(Math.random()*900)+100)}`
  );
  const total = items.reduce((a,i) => a + i.price*i.qty, 0);

  // Next upcoming event for invoice footer
  const todayStr = today();
  const nextEvent = (events||[])
    .filter(e => e.date >= todayStr)
    .sort((a,b)=>a.date.localeCompare(b.date))[0];

  function printInvoice() {
    const dateStr = formatDate(new Date().toISOString());
    const rows = items.map(i =>
      `<tr><td>${i.art}</td><td>${i.description}</td>
       <td style="color:#888;font-style:italic">${i.note||"—"}</td>
       <td style="text-align:right">${i.qty}</td>
       <td style="text-align:right">${i.price.toFixed(2)} €</td>
       <td style="text-align:right"><strong>${(i.price*i.qty).toFixed(2)} €</strong></td></tr>`
    ).join("");

    const eventBlock = nextEvent ? `
      <div class="event-box">
        <div class="event-label">Kommendes Event</div>
        <div class="event-title">${nextEvent.title}</div>
        <div class="event-detail">${nextEvent.type} · ${formatDate(nextEvent.date+"T00:00:00")}${nextEvent.location?" · "+nextEvent.location:""}</div>
        ${nextEvent.note?`<div class="event-note">${nextEvent.note}</div>`:""}
      </div>` : "";

    const html = `<!DOCTYPE html><html><head><meta charset="utf-8">
    <title>Rechnung ${invoiceNr}</title>
    <style>
      @import url('https://fonts.googleapis.com/css2?family=EB+Garamond:ital,wght@0,400;0,600;1,400&display=swap');
      *{box-sizing:border-box;margin:0;padding:0;}
      body{font-family:'EB Garamond',Georgia,serif;color:#2a1035;background:#fff;}
      .page{max-width:740px;margin:48px auto;padding:0 44px 60px;}
      .header{display:flex;justify-content:space-between;align-items:flex-start;padding-bottom:20px;border-bottom:3px solid #7B2D8B;margin-bottom:36px;}
      .logo-wrap{display:flex;align-items:center;gap:16px;}
      .logo-img{width:54px;height:54px;object-fit:cover;border-radius:50%;border:2px solid #C87FD8;}
      .brand-name{font-size:24px;letter-spacing:1px;font-weight:600;color:#4A1260;}
      .brand-gold{font-size:10px;letter-spacing:3px;text-transform:uppercase;color:#7B2D8B;margin-top:3px;}
      .brand-details{font-size:11px;color:#888;line-height:2;margin-top:5px;}
      .invoice-meta{text-align:right;font-size:13px;line-height:1.9;}
      .invoice-meta .nr{font-size:20px;font-weight:600;letter-spacing:1px;display:block;margin-bottom:4px;color:#4A1260;}
      .columns{display:flex;justify-content:space-between;margin-bottom:36px;gap:24px;}
      .col{flex:1;}
      .col-label{font-size:10px;letter-spacing:3px;text-transform:uppercase;color:#7B2D8B;margin-bottom:8px;}
      .col-content{font-size:13px;line-height:1.9;}
      table{width:100%;border-collapse:collapse;margin-bottom:8px;}
      thead tr{border-bottom:2px solid #7B2D8B;}
      th{font-size:10px;letter-spacing:2px;text-transform:uppercase;color:#888;padding:8px 10px;text-align:left;font-weight:normal;}
      td{padding:11px 10px;font-size:13px;border-bottom:1px solid #7B2D8B22;vertical-align:top;}
      .total-row td{border-top:2px solid #7B2D8B;border-bottom:none;padding-top:14px;font-size:16px;font-weight:600;}
      .thanks{margin-top:32px;padding:20px 24px;background:#F2E6F6;border-left:4px solid #7B2D8B;border-radius:4px;font-size:13px;line-height:1.9;color:#4A1260;font-style:italic;}
      .event-box{margin-top:24px;padding:16px 20px;border:1px solid #C87FD8;border-radius:6px;background:#FAF6FD;}
      .event-label{font-size:10px;letter-spacing:3px;text-transform:uppercase;color:#7B2D8B;margin-bottom:6px;}
      .event-title{font-size:15px;font-weight:600;color:#4A1260;}
      .event-detail{font-size:12px;color:#888;margin-top:3px;}
      .event-note{font-size:12px;color:#666;font-style:italic;margin-top:4px;}
      .footer{margin-top:40px;padding-top:16px;border-top:1px solid #7B2D8B33;font-size:11px;color:#aaa;letter-spacing:0.5px;line-height:1.9;}
      @media print{body{-webkit-print-color-adjust:exact;}}
    </style></head>
    <body><div class="page">
      <div class="header">
        <div class="logo-wrap">
          <img class="logo-img" src="data:image/jpeg;base64," alt="Surkow Art Logo"/>
          <div>
            <div class="brand-name">${FIRMA.name}</div>
            <div class="brand-gold">${FIRMA.atelier}</div>
            <div class="brand-details">${FIRMA.kuenstler} · ${FIRMA.adresse} · ${FIRMA.plzOrt}<br>${FIRMA.email} · ${FIRMA.web}</div>
          </div>
        </div>
        <div class="invoice-meta">
          <span class="nr">${invoiceNr}</span>Datum: ${dateStr}
        </div>
      </div>
      <div class="columns">
        <div class="col"><div class="col-label">Von</div>
          <div class="col-content"><strong>${FIRMA.name}</strong><br>${FIRMA.kuenstler}<br>${FIRMA.adresse}<br>${FIRMA.plzOrt}<br>${FIRMA.email}</div>
        </div>
        <div class="col"><div class="col-label">An</div>
          <div class="col-content"><strong>${customer.name||"—"}</strong><br>${customer.address||""}${customer.address?"<br>":""}${customer.city||""}${customer.city?"<br>":""}${customer.email||""}</div>
        </div>
      </div>
      <table>
        <thead><tr><th>Artikelart</th><th>Beschreibung</th><th>Notiz</th><th style="text-align:right">Stk.</th><th style="text-align:right">Preis/Stk.</th><th style="text-align:right">Gesamt</th></tr></thead>
        <tbody>${rows}
          <tr class="total-row"><td colspan="5">Gesamtbetrag</td><td style="text-align:right">${total.toFixed(2)} €</td></tr>
        </tbody>
      </table>
      <div class="thanks">
        Herzlichen Dank für Ihren Einkauf und Ihr Vertrauen in meine Arbeit!<br>
        Ich wünsche Ihnen viel Freude an Ihrem neuen Kunstwerk — möge es Ihnen täglich Inspiration und Freude schenken.<br><br>
        Mit künstlerischen Grüßen,<br><strong>${FIRMA.kuenstler}</strong>
      </div>
      ${eventBlock}
      <div class="footer">${FIRMA.name} · ${FIRMA.kuenstler} · ${FIRMA.adresse} · ${FIRMA.plzOrt} · ${FIRMA.email} · ${FIRMA.web}<br>Kleinunternehmer gem. § 19 UStG – Es wird keine Umsatzsteuer berechnet.</div>
    </div></body></html>`;
    const w = window.open("","_blank");
    w.document.write(html);
    w.document.close();
    setTimeout(()=>w.print(),700);
  }

  return (
    <div style={{position:"fixed",inset:0,background:"#4A126099",zIndex:200,display:"flex",alignItems:"center",justifyContent:"center",padding:16}}>
      <div style={{background:C.cream,borderRadius:12,padding:28,width:"100%",maxWidth:520,maxHeight:"90vh",overflowY:"auto",boxShadow:"0 8px 40px #4A126033",border:`2px solid ${C.purpleLt}`}}>
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:20}}>
          <div>
            <div style={{fontSize:11,letterSpacing:3,textTransform:"uppercase",color:C.purple}}>Rechnung erstellen</div>
            <div style={{fontSize:18,color:C.purpleDk,fontWeight:"bold"}}>{invoiceNr}</div>
          </div>
          <button onClick={onClose} style={{background:"none",border:"none",cursor:"pointer",fontSize:24,color:C.purple}}>×</button>
        </div>
        <div style={{fontSize:11,letterSpacing:2,textTransform:"uppercase",color:C.grey,marginBottom:10}}>Kundendaten</div>
        <div style={{display:"flex",flexDirection:"column",gap:8,marginBottom:20}}>
          {[["Name","name"],["Adresse","address"],["PLZ / Stadt","city"],["E-Mail (optional)","email"]].map(([ph,field])=>(
            <input key={field} placeholder={ph} value={customer[field]} onChange={e=>setCustomer(c=>({...c,[field]:e.target.value}))} style={inp}/>
          ))}
          <input placeholder="Rechnungsnummer" value={invoiceNr} onChange={e=>setInvoiceNr(e.target.value)} style={inp}/>
        </div>
        <div style={{fontSize:11,letterSpacing:2,textTransform:"uppercase",color:C.grey,marginBottom:10}}>Positionen</div>
        <div style={{background:"#fff",borderRadius:8,border:`1px solid ${C.purpleLt}55`,marginBottom:20,overflow:"hidden"}}>
          {items.map((item,i)=>(
            <div key={i} style={{padding:"10px 14px",borderBottom:`1px solid ${C.purpleXlt}`,display:"flex",justifyContent:"space-between",fontSize:13,gap:12}}>
              <div style={{flex:1}}>
                <div style={{fontWeight:"bold",color:C.purpleDk}}>{item.art}</div>
                <div style={{color:"#555"}}>{item.description}</div>
                {item.note&&<div style={{fontSize:12,color:"#aaa",fontStyle:"italic"}}>{item.note}</div>}
              </div>
              <div style={{textAlign:"right",whiteSpace:"nowrap",color:C.green}}>
                {item.qty}×{item.price.toFixed(2)}€<br/><strong>{(item.qty*item.price).toFixed(2)}€</strong>
              </div>
            </div>
          ))}
          <div style={{padding:"12px 14px",display:"flex",justifyContent:"space-between",fontWeight:"bold",fontSize:16,background:C.purpleDk,color:"#fff"}}>
            <span>Gesamtbetrag</span><span>{total.toFixed(2)} €</span>
          </div>
        </div>
        {nextEvent && (
          <div style={{marginBottom:16,padding:"12px 16px",background:C.purpleXlt,borderRadius:8,border:`1px solid ${C.purpleLt}`,fontSize:13}}>
            <div style={{fontSize:10,letterSpacing:2,textTransform:"uppercase",color:C.purple,marginBottom:4}}>Nächstes Event wird auf Rechnung angezeigt</div>
            <div style={{fontWeight:"bold",color:C.purpleDk}}>{nextEvent.title}</div>
            <div style={{color:C.grey}}>{nextEvent.type} · {formatDate(nextEvent.date+"T00:00:00")}</div>
          </div>
        )}
        <button onClick={printInvoice} style={{...mkBtn(),width:"100%",padding:"14px",fontSize:14,letterSpacing:2}}>
          Rechnung drucken / Als PDF speichern
        </button>
      </div>
    </div>
  );
}

// ── Calendar Component ──────────────────────────────────────────────────────────
function CalendarTab({ events, setData }) {
  const now = new Date();
  const [viewYear, setViewYear]  = useState(now.getFullYear());
  const [viewMonth, setViewMonth] = useState(now.getMonth());
  const [form, setForm]  = useState({ title:"", type:"Auftragsarbeit", date:"", location:"", note:"" });
  const [formErr, setFormErr] = useState("");
  const [selectedDay, setSelectedDay] = useState(null);

  function daysInMonth(y, m) { return new Date(y, m+1, 0).getDate(); }
  function firstDayOfMonth(y, m) {
    const d = new Date(y, m, 1).getDay();
    return d === 0 ? 6 : d - 1; // Mon=0
  }

  const todayStr = today();
  const days = daysInMonth(viewYear, viewMonth);
  const firstDay = firstDayOfMonth(viewYear, viewMonth);

  const eventsByDate = {};
  events.forEach(e => {
    if (!eventsByDate[e.date]) eventsByDate[e.date] = [];
    eventsByDate[e.date].push(e);
  });

  function prevMonth() { if(viewMonth===0){setViewMonth(11);setViewYear(y=>y-1);}else setViewMonth(m=>m-1); }
  function nextMonth() { if(viewMonth===11){setViewMonth(0);setViewYear(y=>y+1);}else setViewMonth(m=>m+1); }

  function saveEvent() {
    if (!form.title.trim() || !form.date) { setFormErr("Bitte Titel und Datum eingeben."); return; }
    setFormErr("");
    setData(d => ({ ...d, events: [...(d.events||[]), { id:crypto.randomUUID(), ...form }] }));
    setForm({ title:"", type:"Auftragsarbeit", date:"", location:"", note:"" });
  }
  function deleteEvent(id) { setData(d => ({ ...d, events: (d.events||[]).filter(e=>e.id!==id) })); }

  const selectedDateStr = selectedDay
    ? `${viewYear}-${String(viewMonth+1).padStart(2,"0")}-${String(selectedDay).padStart(2,"0")}`
    : null;
  const selectedEvents = selectedDateStr ? (eventsByDate[selectedDateStr]||[]) : [];

  return (
    <div style={{paddingTop:24}}>
      {/* Calendar grid */}
      <div style={{background:"#fff",border:`1px solid ${C.purpleLt}55`,borderRadius:12,marginBottom:20,overflow:"hidden",boxShadow:`0 2px 12px ${C.purple}0a`}}>
        <div style={{background:C.purpleDk,padding:"14px 18px",display:"flex",justifyContent:"space-between",alignItems:"center"}}>
          <button onClick={prevMonth} style={{background:"none",border:"none",cursor:"pointer",color:"#fff",fontSize:20,padding:"0 8px"}}>‹</button>
          <span style={{color:"#fff",fontSize:16,letterSpacing:2,fontFamily:"Georgia,serif"}}>{MONTHS_LONG[viewMonth]} {viewYear}</span>
          <button onClick={nextMonth} style={{background:"none",border:"none",cursor:"pointer",color:"#fff",fontSize:20,padding:"0 8px"}}>›</button>
        </div>
        <div style={{display:"grid",gridTemplateColumns:"repeat(7,1fr)",background:C.purpleXlt}}>
          {DAYS_SHORT.map(d=>(
            <div key={d} style={{textAlign:"center",padding:"8px 0",fontSize:11,letterSpacing:1,textTransform:"uppercase",color:C.purple,fontWeight:"bold"}}>{d}</div>
          ))}
        </div>
        <div style={{display:"grid",gridTemplateColumns:"repeat(7,1fr)"}}>
          {Array.from({length:firstDay}).map((_,i)=>(
            <div key={"e"+i} style={{minHeight:54,borderRight:`1px solid ${C.purpleXlt}`,borderBottom:`1px solid ${C.purpleXlt}`}}/>
          ))}
          {Array.from({length:days}).map((_,i)=>{
            const day = i+1;
            const dateStr = `${viewYear}-${String(viewMonth+1).padStart(2,"0")}-${String(day).padStart(2,"0")}`;
            const dayEvents = eventsByDate[dateStr]||[];
            const isToday = dateStr === todayStr;
            const isSelected = day === selectedDay;
            return (
              <div key={day} onClick={()=>setSelectedDay(day===selectedDay?null:day)}
                style={{minHeight:54,padding:"4px 6px",borderRight:`1px solid ${C.purpleXlt}`,borderBottom:`1px solid ${C.purpleXlt}`,
                  cursor:"pointer",background:isSelected?C.purpleXlt:isToday?"#FFF0FF":"#fff",
                  transition:"background 0.15s"}}>
                <div style={{fontSize:13,fontWeight:isToday?"bold":"normal",color:isToday?C.purple:C.darkText,
                  background:isToday?C.purpleLt:"none",width:22,height:22,borderRadius:"50%",
                  display:"flex",alignItems:"center",justifyContent:"center"}}>{day}</div>
                {dayEvents.slice(0,2).map((ev,j)=>(
                  <div key={j} style={{fontSize:10,background: ev.type==="Auftragsarbeit"?C.purple:C.purpleMd,
                    color:"#fff",borderRadius:3,padding:"1px 4px",marginTop:2,overflow:"hidden",whiteSpace:"nowrap",textOverflow:"ellipsis"}}>{ev.title}</div>
                ))}
                {dayEvents.length>2&&<div style={{fontSize:10,color:C.purple}}>+{dayEvents.length-2}</div>}
              </div>
            );
          })}
        </div>
      </div>

      {/* Selected day events */}
      {selectedDateStr && (
        <div style={{background:"#fff",border:`1px solid ${C.purpleLt}55`,borderRadius:10,padding:18,marginBottom:20}}>
          <div style={{fontSize:11,letterSpacing:2,textTransform:"uppercase",color:C.grey,marginBottom:10}}>
            {formatDate(selectedDateStr+"T00:00:00")}
          </div>
          {selectedEvents.length===0 ? (
            <div style={{color:C.grey,fontSize:13,fontStyle:"italic"}}>Keine Termine an diesem Tag.</div>
          ) : selectedEvents.map(ev=>(
            <div key={ev.id} style={{display:"flex",alignItems:"flex-start",gap:10,padding:"10px 0",borderBottom:`1px solid ${C.purpleXlt}`}}>
              <div style={{flex:1}}>
                <div style={{fontWeight:"bold",color:C.purpleDk,fontSize:14}}>{ev.title}</div>
                <div style={{fontSize:12,color:C.grey,marginTop:2}}>{ev.type}{ev.location?" · "+ev.location:""}</div>
                {ev.note&&<div style={{fontSize:12,color:"#aaa",fontStyle:"italic",marginTop:2}}>{ev.note}</div>}
              </div>
              <button onClick={()=>deleteEvent(ev.id)} style={{background:"none",border:"none",cursor:"pointer",color:C.purpleLt,fontSize:18,lineHeight:1}}>×</button>
            </div>
          ))}
        </div>
      )}

      {/* New event form */}
      <div style={{background:"#fff",border:`1px solid ${C.purpleLt}55`,borderRadius:10,padding:22,boxShadow:`0 2px 12px ${C.purple}0a`}}>
        <div style={{fontSize:11,letterSpacing:3,textTransform:"uppercase",color:C.grey,marginBottom:14}}>Neuer Termin</div>
        <div style={{display:"flex",flexDirection:"column",gap:10}}>
          <select value={form.type} onChange={e=>setForm(f=>({...f,type:e.target.value}))} style={inp}>
            {EVENT_TYPES.map(t=><option key={t}>{t}</option>)}
          </select>
          <input placeholder="Titel *" value={form.title} onChange={e=>setForm(f=>({...f,title:e.target.value}))} style={inp}/>
          <input type="date" value={form.date} onChange={e=>setForm(f=>({...f,date:e.target.value}))} style={inp}/>
          <input placeholder="Ort (optional)" value={form.location} onChange={e=>setForm(f=>({...f,location:e.target.value}))} style={inp}/>
          <textarea placeholder="Notiz (optional)" value={form.note} onChange={e=>setForm(f=>({...f,note:e.target.value}))} rows={2} style={{...inp,resize:"none"}}/>
          {formErr&&<div style={{color:C.red,fontSize:13}}>{formErr}</div>}
          <button onClick={saveEvent} style={{...mkBtn(),padding:"12px",width:"100%"}}>Termin speichern</button>
        </div>
      </div>

      {/* Upcoming list */}
      {events.filter(e=>e.date>=todayStr).sort((a,b)=>a.date.localeCompare(b.date)).length>0 && (
        <div style={{marginTop:20,paddingBottom:20}}>
          <div style={{fontSize:11,letterSpacing:3,textTransform:"uppercase",color:C.grey,marginBottom:12}}>Kommende Termine</div>
          {events.filter(e=>e.date>=todayStr).sort((a,b)=>a.date.localeCompare(b.date)).map(ev=>(
            <div key={ev.id} style={{display:"flex",alignItems:"center",background:"#fff",border:`1px solid ${C.purpleLt}55`,borderRadius:8,padding:"11px 14px",marginBottom:7,gap:10}}>
              <div style={{width:44,height:44,borderRadius:8,background:C.purpleXlt,display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",flexShrink:0,border:`1px solid ${C.purpleLt}`}}>
                <div style={{fontSize:10,color:C.purple,textTransform:"uppercase",letterSpacing:0.5}}>{MONTHS_SHORT[new Date(ev.date+"T00:00:00").getMonth()]}</div>
                <div style={{fontSize:18,fontWeight:"bold",color:C.purpleDk,lineHeight:1}}>{new Date(ev.date+"T00:00:00").getDate()}</div>
              </div>
              <div style={{flex:1}}>
                <div style={{fontSize:14,fontWeight:"bold",color:C.purpleDk}}>{ev.title}</div>
                <div style={{fontSize:12,color:C.grey}}>{ev.type}{ev.location?" · "+ev.location:""}</div>
              </div>
              <button onClick={()=>deleteEvent(ev.id)} style={{background:"none",border:"none",cursor:"pointer",color:C.purpleLt,fontSize:18,lineHeight:1}}>×</button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

// ── Month Card (collapsible) ──────────────────────────────────────────────────
function MonthCard({ monthKey, sessions, expenses, incomes }) {
  const [open, setOpen] = useState(false);
  const totalH = sessions.reduce((a,s)=>a+s.duration,0);
  const totalE = expenses.reduce((a,e)=>a+e.amount,0);
  const totalI = incomes.reduce((a,i)=>a+i.price*i.qty,0);
  const p = totalI - totalE;
  return (
    <div style={{background:"#fff",border:`1px solid ${C.purpleLt}55`,borderRadius:10,marginBottom:14,overflow:"hidden"}}>
      <button onClick={()=>setOpen(o=>!o)} style={{width:"100%",background:C.purpleDk,border:"none",cursor:"pointer",
        padding:"13px 18px",display:"flex",justifyContent:"space-between",alignItems:"center",flexWrap:"wrap",gap:8,fontFamily:"Georgia,serif"}}>
        <div style={{display:"flex",alignItems:"center",gap:10}}>
          <span style={{color:"#fff",letterSpacing:2,fontSize:14}}>{monthLabel(monthKey)}</span>
          <span style={{color:C.purpleLt,fontSize:11}}>{open?"▲":"▼"}</span>
        </div>
        <div style={{fontSize:12,letterSpacing:1,display:"flex",gap:14,flexWrap:"wrap"}}>
          <span style={{color:C.purpleLt}}>{formatDuration(totalH)}</span>
          {totalI>0&&<span style={{color:"#90EE90"}}>+{totalI.toFixed(2)} €</span>}
          {totalE>0&&<span style={{color:"#FFB3B3"}}>−{totalE.toFixed(2)} €</span>}
          {(totalI>0||totalE>0)&&<span style={{color:p>=0?"#90EE90":"#FFB3B3",fontWeight:"bold"}}>= {p>=0?"+":""}{p.toFixed(2)} €</span>}
        </div>
      </button>
      {open&&(
        <div style={{padding:"16px 18px"}}>
          {sessions.length>0&&(
            <Sec label="Atelierstunden">
              {sessions.map(s=><Row key={s.id} left={`${formatDate(s.start)} · ${formatTime(s.start)}–${formatTime(s.end)}${s.note?" · "+s.note:""}`} right={formatDuration(s.duration)}/>)}
              {sessions.some(s=>s.pausedMs>0)&&<div style={{fontSize:11,color:C.purpleLt,padding:"3px 0"}}>Pausen: {formatDuration(sessions.reduce((a,s)=>a+(s.pausedMs||0),0))}</div>}
              <Row left="Gesamt Atelierstunden" right={formatDuration(totalH)} bold/>
            </Sec>
          )}
          {incomes.length>0&&(
            <Sec label="Einnahmen" mt={sessions.length>0}>
              {incomes.map(i=><Row key={i.id} left={`${i.description} (${i.art}${i.qty>1?", "+i.qty+" Stk.":""})`} right={(i.price*i.qty).toFixed(2)+" €"} color={C.green}/>)}
              <Row left="Gesamt Einnahmen" right={totalI.toFixed(2)+" €"} bold color={C.green}/>
            </Sec>
          )}
          {expenses.length>0&&(
            <Sec label="Ausgaben" mt>
              {expenses.map(e=><Row key={e.id} left={`${formatDate(e.date+"T00:00:00")} · ${e.description} (${e.category})`} right={e.amount.toFixed(2)+" €"}/>)}
              <Row left="Gesamt Ausgaben" right={totalE.toFixed(2)+" €"} bold color={C.red}/>
            </Sec>
          )}
          {(totalI>0||totalE>0)&&(
            <div style={{marginTop:14,paddingTop:10,borderTop:`2px solid ${C.purpleDk}`,display:"flex",justifyContent:"space-between",fontSize:14,fontWeight:"bold"}}>
              <span>Monatsergebnis</span>
              <span style={{color:p>=0?C.green:C.red}}>{p>=0?"+":""}{p.toFixed(2)} €</span>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

function Sec({ label, children, mt }) {
  return (
    <div style={{marginTop:mt?18:0}}>
      <div style={{fontSize:10,letterSpacing:2,textTransform:"uppercase",color:C.purpleMd,marginBottom:7}}>{label}</div>
      {children}
    </div>
  );
}
function Row({ left, right, bold, color }) {
  return (
    <div style={{display:"flex",justifyContent:"space-between",fontSize:13,padding:"5px 0",borderBottom:`1px solid ${C.purpleXlt}`,fontWeight:bold?"bold":"normal"}}>
      <span style={{color:bold?C.darkText:C.grey,flex:1,paddingRight:12}}>{left}</span>
      <span style={{color:color||(bold?C.darkText:C.darkText),fontVariantNumeric:"tabular-nums",whiteSpace:"nowrap"}}>{right}</span>
    </div>
  );
}

// ── Invoice Builder ──────────────────────────────────────────────────────────
function InvoiceBuilder({ incomes, onInvoice }) {
  const [selected, setSelected] = useState({});
  const toggle = id => setSelected(s=>({...s,[id]:!s[id]}));
  const sel = incomes.filter(i=>selected[i.id]);
  return (
    <div style={{background:"#fff",border:`1px solid ${C.purpleLt}55`,borderRadius:10,padding:20,marginBottom:24}}>
      <div style={{fontSize:11,letterSpacing:3,textTransform:"uppercase",color:C.grey,marginBottom:4}}>Rechnung erstellen</div>
      <div style={{fontSize:13,color:"#aaa",marginBottom:14}}>Positionen auswählen</div>
      <div style={{display:"flex",flexDirection:"column",gap:6,marginBottom:14}}>
        {incomes.slice(0,30).map(i=>(
          <label key={i.id} style={{display:"flex",alignItems:"center",gap:10,cursor:"pointer",fontSize:13,
            padding:"9px 12px",background:selected[i.id]?C.purpleXlt:"#fafafa",
            border:`1px solid ${selected[i.id]?C.purple:C.purpleLt+"55"}`,borderRadius:6,transition:"all 0.15s"}}>
            <input type="checkbox" checked={!!selected[i.id]} onChange={()=>toggle(i.id)} style={{accentColor:C.purple}}/>
            <span style={{flex:1}}>{i.description} <span style={{color:"#aaa"}}>· {i.art}</span></span>
            <span style={{color:C.green,fontVariantNumeric:"tabular-nums",whiteSpace:"nowrap"}}>
              {i.qty>1?`${i.qty}×${i.price.toFixed(2)} = `:""}{(i.price*i.qty).toFixed(2)} €
            </span>
          </label>
        ))}
      </div>
      <button onClick={()=>sel.length>0&&onInvoice(sel)}
        style={{...mkBtn(sel.length>0?C.purple:"#ccc",sel.length>0?"#fff":"#999"),padding:"11px 24px",opacity:sel.length>0?1:0.6}}>
        {sel.length>0?`Rechnung: ${sel.length} Pos. · ${sel.reduce((a,i)=>a+i.price*i.qty,0).toFixed(2)} €`:"Keine Position gewählt"}
      </button>
    </div>
  );
}

// ── Main App ─────────────────────────────────────────────────────────────────
export default function AtelierTracker() {
  const [data, setData]   = useState(loadData);
  const [tab, setTab]     = useState("stempel");
  const [invoiceItems, setInvoiceItems] = useState(null);

  // Timer
  const [timerState, setTimerState] = useState("stopped");
  const [startTime, setStartTime]   = useState(null);
  const [elapsed, setElapsed]       = useState(0);
  const [pauseStart, setPauseStart] = useState(null);
  const [totalPaused, setTotalPaused] = useState(0);
  const [sessionNote, setSessionNote] = useState("");
  const timerRef = useRef(null);

  // Forms
  const [expForm, setExpForm] = useState({ description:"", amount:"", category:"Rahmen", date:today() });
  const [expErr,  setExpErr]  = useState("");
  const [incForm, setIncForm] = useState({ art:"Original Gemälde", description:"", price:"", qty:"1", note:"", date:today() });
  const [incErr,  setIncErr]  = useState("");

  useEffect(()=>{ saveData(data); },[data]);
  useEffect(()=>{
    if(timerState==="running"){ timerRef.current=setInterval(()=>setElapsed(Date.now()-startTime-totalPaused),1000);}
    else clearInterval(timerRef.current);
    return ()=>clearInterval(timerRef.current);
  },[timerState,startTime,totalPaused]);

  function handleStart(){ setStartTime(Date.now());setElapsed(0);setTotalPaused(0);setPauseStart(null);setTimerState("running"); }
  function handlePause(){
    if(timerState==="running"){setPauseStart(Date.now());setTimerState("paused");}
    else{const p=Date.now()-pauseStart;setTotalPaused(t=>t+p);setPauseStart(null);setTimerState("running");}
  }
  function handleStop(){
    const end=Date.now(),extra=timerState==="paused"?(end-pauseStart):0;
    const duration=Math.max(0,end-startTime-totalPaused-extra);
    setData(d=>({...d,sessions:[{id:crypto.randomUUID(),start:new Date(startTime).toISOString(),end:new Date(end).toISOString(),duration,pausedMs:totalPaused+extra,note:sessionNote.trim()},...d.sessions]}));
    setTimerState("stopped");setElapsed(0);setTotalPaused(0);setSessionNote("");
  }
  function deleteSession(id){ setData(d=>({...d,sessions:d.sessions.filter(s=>s.id!==id)})); }

  function handleExpSave(){
    if(!expForm.description.trim()||isNaN(parseFloat(expForm.amount))){setExpErr("Bitte Beschreibung und Betrag.");return;}
    setExpErr("");
    setData(d=>({...d,expenses:[{id:crypto.randomUUID(),...expForm,amount:parseFloat(expForm.amount)},...d.expenses]}));
    setExpForm({description:"",amount:"",category:"Rahmen",date:today()});
  }
  function deleteExpense(id){ setData(d=>({...d,expenses:d.expenses.filter(e=>e.id!==id)})); }

  function handleIncSave(){
    if(!incForm.description.trim()||isNaN(parseFloat(incForm.price))||isNaN(parseInt(incForm.qty))){setIncErr("Bitte alle Felder ausfüllen.");return;}
    setIncErr("");
    setData(d=>({...d,incomes:[{id:crypto.randomUUID(),art:incForm.art,description:incForm.description.trim(),price:parseFloat(incForm.price),qty:parseInt(incForm.qty),note:incForm.note.trim(),date:incForm.date},...d.incomes]}));
    setIncForm({art:"Original Gemälde",description:"",price:"",qty:"1",note:"",date:today()});
  }
  function deleteIncome(id){ setData(d=>({...d,incomes:d.incomes.filter(i=>i.id!==id)})); }

  const totalMs  = data.sessions.reduce((a,s)=>a+s.duration,0);
  const totalExp = data.expenses.reduce((a,e)=>a+e.amount,0);
  const totalInc = data.incomes.reduce((a,i)=>a+i.price*i.qty,0);
  const profit   = totalInc - totalExp;

  const sessionsByMonth = groupByMonth(data.sessions);
  const expByMonth      = groupByMonth(data.expenses,"date");
  const incByMonth      = groupByMonth(data.incomes,"date");
  const allKeys = [...new Set([...Object.keys(sessionsByMonth),...Object.keys(expByMonth),...Object.keys(incByMonth)])].sort().reverse();

  // Upcoming event reminders (within 7 days)
  const todayStr = today();
  const todayDate = new Date(todayStr);
  const upcomingReminders = (data.events||[]).filter(e=>{
    const d = new Date(e.date+"T00:00:00");
    const diff = (d - todayDate) / (1000*60*60*24);
    return diff >= 0 && diff <= 7;
  }).sort((a,b)=>a.date.localeCompare(b.date));

  const TABS = [["stempel","Stempeluhr"],["ausgaben","Ausgaben"],["einnahmen","Einnahmen"],["kalender","Kalender"],["uebersicht","Übersicht"]];

  return (
    <div style={{minHeight:"100vh",background:C.cream,fontFamily:"Georgia,'Times New Roman',serif",color:C.darkText}}>
      {invoiceItems&&<InvoiceModal items={invoiceItems} events={data.events||[]} onClose={()=>setInvoiceItems(null)}/>}

      {/* Header */}
      <div style={{background:`linear-gradient(135deg, ${C.purpleDk} 0%, ${C.purple} 100%)`,color:"#fff",padding:"22px 24px 18px",borderBottom:`4px solid ${C.purpleLt}`}}>
        <div style={{maxWidth:700,margin:"0 auto",display:"flex",alignItems:"center",gap:18}}>
          <div style={{width:58,height:58,borderRadius:"50%",overflow:"hidden",border:`3px solid ${C.purpleLt}`,flexShrink:0,background:C.purpleDk}}>
            <img src="data:image/jpeg;base64," alt="Surkow Art" style={{width:"100%",height:"100%",objectFit:"cover"}}/>
          </div>
          <div style={{flex:1}}>
            <div style={{fontSize:11,letterSpacing:4,color:C.purpleLt,textTransform:"uppercase",marginBottom:3}}>{FIRMA.atelier}</div>
            <h1 style={{margin:"0 0 4px",fontSize:24,fontWeight:"normal",letterSpacing:1}}>{FIRMA.name}</h1>
            <div style={{fontSize:11,color:"#ffffff88",letterSpacing:0.3}}>{FIRMA.kuenstler} · {FIRMA.adresse}, {FIRMA.plzOrt} · {FIRMA.email}</div>
          </div>
        </div>
      </div>

      {/* Summary bar */}
      <div style={{background:C.purpleMd,padding:"10px 16px",display:"flex",justifyContent:"center",flexWrap:"wrap"}}>
        {[["Stunden",formatDuration(totalMs),null],["+Einnahmen",`${totalInc.toFixed(2)} €`,"#c8ffcc"],["−Ausgaben",`${totalExp.toFixed(2)} €`,"#ffc8c8"],["Gewinn",`${profit>=0?"+":""}${profit.toFixed(2)} €`,profit>=0?"#c8ffcc":"#ffc8c8"]].map(([label,val,color],i,arr)=>(
          <div key={label} style={{display:"flex",alignItems:"center"}}>
            <div style={{textAlign:"center",padding:"2px 16px"}}>
              <div style={{fontSize:10,letterSpacing:2,textTransform:"uppercase",color:"#ffffff99"}}>{label}</div>
              <div style={{fontSize:16,fontWeight:"bold",color:color||"#fff"}}>{val}</div>
            </div>
            {i<arr.length-1&&<div style={{width:1,height:28,background:"#ffffff30"}}/>}
          </div>
        ))}
      </div>

      <div style={{maxWidth:700,margin:"0 auto",padding:"0 20px"}}>
        {/* Reminders */}
        {upcomingReminders.length>0&&(
          <div style={{marginTop:20,padding:"14px 18px",background:"#fff",border:`2px solid ${C.purple}`,borderRadius:10,boxShadow:`0 4px 16px ${C.purple}22`}}>
            <div style={{fontSize:11,letterSpacing:2,textTransform:"uppercase",color:C.purple,marginBottom:8}}>⚡ Bevorstehende Termine</div>
            {upcomingReminders.map(ev=>{
              const daysLeft = Math.round((new Date(ev.date+"T00:00:00")-todayDate)/(1000*60*60*24));
              return (
                <div key={ev.id} style={{display:"flex",justifyContent:"space-between",alignItems:"center",padding:"6px 0",borderBottom:`1px solid ${C.purpleXlt}`}}>
                  <div>
                    <span style={{fontWeight:"bold",color:C.purpleDk}}>{ev.title}</span>
                    <span style={{color:C.grey,fontSize:12}}> · {ev.type}{ev.location?" · "+ev.location:""}</span>
                  </div>
                  <div style={{fontSize:12,color:daysLeft===0?C.red:C.purple,fontWeight:"bold",whiteSpace:"nowrap",marginLeft:10}}>
                    {daysLeft===0?"Heute":daysLeft===1?"Morgen":`in ${daysLeft} Tagen`}
                  </div>
                </div>
              );
            })}
          </div>
        )}

        {/* Tabs */}
        <div style={{display:"flex",marginTop:22,borderBottom:`2px solid ${C.purpleLt}33`,overflowX:"auto"}}>
          {TABS.map(([key,label])=>(
            <button key={key} onClick={()=>setTab(key)} style={{background:"none",border:"none",borderBottom:tab===key?`2px solid ${C.purple}`:"2px solid transparent",padding:"10px 14px",marginBottom:-2,cursor:"pointer",fontSize:13,letterSpacing:1,whiteSpace:"nowrap",color:tab===key?C.purple:C.grey,fontFamily:"Georgia,serif",fontWeight:tab===key?"bold":"normal",transition:"color 0.2s"}}>{label}</button>
          ))}
        </div>

        {/* ══ STEMPELUHR ══ */}
        {tab==="stempel"&&(
          <div style={{paddingTop:24}}>
            <div style={{textAlign:"center",background:"#fff",border:`1px solid ${C.purpleLt}55`,borderRadius:12,padding:"36px 24px 28px",marginBottom:24,boxShadow:`0 2px 12px ${C.purple}0a`}}>
              <div style={{fontSize:52,fontVariantNumeric:"tabular-nums",letterSpacing:4,marginBottom:6,
                color:timerState==="paused"?C.purpleLt:timerState==="running"?C.purple:C.purpleDk,transition:"color 0.3s"}}>
                {formatDuration(elapsed)}
              </div>
              {timerState!=="stopped"&&(
                <div style={{fontSize:12,letterSpacing:2,textTransform:"uppercase",marginBottom:16,color:timerState==="paused"?C.purpleLt:C.purple}}>
                  {timerState==="paused"?"⏸  Pause läuft":`● Läuft seit ${formatTime(new Date(startTime).toISOString())}`}
                </div>
              )}
              <textarea placeholder="Notiz zur Sitzung (optional)" value={sessionNote} onChange={e=>setSessionNote(e.target.value)} rows={2}
                style={{...inp,maxWidth:360,resize:"none",display:"block",margin:"0 auto 22px"}}/>
              <div style={{display:"flex",gap:10,justifyContent:"center",flexWrap:"wrap"}}>
                {timerState==="stopped"&&<button onClick={handleStart} style={{...mkBtn(),padding:"13px 40px",letterSpacing:2}}>Arbeitsbeginn</button>}
                {timerState!=="stopped"&&<>
                  <button onClick={handlePause} style={{...mkBtn(timerState==="paused"?C.purpleLt:C.purpleMd,timerState==="paused"?C.darkText:"#fff"),padding:"13px 26px"}}>
                    {timerState==="paused"?"▶  Weiter":"⏸  Pause"}
                  </button>
                  <button onClick={handleStop} style={{...mkBtn(C.red),padding:"13px 26px"}}>Feierabend</button>
                </>}
              </div>
            </div>
            <div style={{fontSize:11,letterSpacing:3,textTransform:"uppercase",color:C.grey,marginBottom:12}}>Letzte Sitzungen</div>
            {data.sessions.length===0&&<div style={{color:C.grey,fontSize:14,fontStyle:"italic"}}>Noch keine Sitzungen.</div>}
            {data.sessions.slice(0,10).map(s=>(
              <div key={s.id} style={{display:"flex",alignItems:"center",background:"#fff",border:`1px solid ${C.purpleLt}33`,borderRadius:8,padding:"11px 14px",marginBottom:7,gap:10}}>
                <div style={{flex:1,minWidth:0}}>
                  <div style={{fontSize:13}}>{formatDate(s.start)} · {formatTime(s.start)} – {formatTime(s.end)}</div>
                  {s.note&&<div style={{fontSize:12,color:C.grey,fontStyle:"italic",marginTop:2}}>{s.note}</div>}
                  {s.pausedMs>0&&<div style={{fontSize:11,color:C.purpleLt,marginTop:2}}>Pause: {formatDuration(s.pausedMs)}</div>}
                </div>
                <div style={{fontSize:15,fontVariantNumeric:"tabular-nums",color:C.purple,minWidth:82,textAlign:"right"}}>{formatDuration(s.duration)}</div>
                <button onClick={()=>deleteSession(s.id)} style={{background:"none",border:"none",cursor:"pointer",color:C.purpleLt,fontSize:20,padding:"0 4px",lineHeight:1}}>×</button>
              </div>
            ))}
          </div>
        )}

        {/* ══ AUSGABEN ══ */}
        {tab==="ausgaben"&&(
          <div style={{paddingTop:24}}>
            <div style={{background:"#fff",border:`1px solid ${C.purpleLt}55`,borderRadius:10,padding:22,marginBottom:24}}>
              <div style={{fontSize:11,letterSpacing:3,textTransform:"uppercase",color:C.grey,marginBottom:14}}>Neue Ausgabe</div>
              <div style={{display:"flex",flexDirection:"column",gap:10}}>
                <input placeholder="Beschreibung" value={expForm.description} onChange={e=>setExpForm(f=>({...f,description:e.target.value}))} style={inp}/>
                <div style={{display:"flex",gap:10}}>
                  <input placeholder="Betrag (€)" type="number" min="0" step="0.01" value={expForm.amount} onChange={e=>setExpForm(f=>({...f,amount:e.target.value}))} style={{...inp,flex:1}}/>
                  <select value={expForm.category} onChange={e=>setExpForm(f=>({...f,category:e.target.value}))} style={{...inp,flex:1}}>{EXPENSE_CATS.map(c=><option key={c}>{c}</option>)}</select>
                </div>
                <input type="date" value={expForm.date} onChange={e=>setExpForm(f=>({...f,date:e.target.value}))} style={inp}/>
                {expErr&&<div style={{color:C.red,fontSize:13}}>{expErr}</div>}
                <button onClick={handleExpSave} style={{...mkBtn(),padding:"12px",width:"100%"}}>Ausgabe speichern</button>
              </div>
            </div>
            <div style={{fontSize:11,letterSpacing:3,textTransform:"uppercase",color:C.grey,marginBottom:12}}>Letzte Ausgaben</div>
            {data.expenses.length===0&&<div style={{color:C.grey,fontSize:14,fontStyle:"italic"}}>Noch keine Ausgaben.</div>}
            {data.expenses.slice(0,20).map(e=>(
              <div key={e.id} style={{display:"flex",alignItems:"center",background:"#fff",border:`1px solid ${C.purpleLt}33`,borderRadius:8,padding:"11px 14px",marginBottom:7,gap:10}}>
                <div style={{flex:1}}><div style={{fontSize:13}}>{e.description}</div><div style={{fontSize:11,color:C.grey,marginTop:2,textTransform:"uppercase",letterSpacing:1}}>{formatDate(e.date+"T00:00:00")} · {e.category}</div></div>
                <div style={{fontSize:15,color:C.red,minWidth:72,textAlign:"right"}}>{e.amount.toFixed(2)} €</div>
                <button onClick={()=>deleteExpense(e.id)} style={{background:"none",border:"none",cursor:"pointer",color:C.purpleLt,fontSize:20,padding:"0 4px",lineHeight:1}}>×</button>
              </div>
            ))}
          </div>
        )}

        {/* ══ EINNAHMEN ══ */}
        {tab==="einnahmen"&&(
          <div style={{paddingTop:24}}>
            <div style={{background:"#fff",border:`1px solid ${C.purpleLt}55`,borderRadius:10,padding:22,marginBottom:24}}>
              <div style={{fontSize:11,letterSpacing:3,textTransform:"uppercase",color:C.grey,marginBottom:14}}>Neue Einnahme</div>
              <div style={{display:"flex",flexDirection:"column",gap:10}}>
                <select value={incForm.art} onChange={e=>setIncForm(f=>({...f,art:e.target.value}))} style={inp}>{INCOME_ARTS.map(a=><option key={a}>{a}</option>)}</select>
                <input placeholder="Titel / Beschreibung *" value={incForm.description} onChange={e=>setIncForm(f=>({...f,description:e.target.value}))} style={inp}/>
                <div style={{display:"flex",gap:10}}>
                  <input placeholder="Preis je Stück (€) *" type="number" min="0" step="0.01" value={incForm.price} onChange={e=>setIncForm(f=>({...f,price:e.target.value}))} style={{...inp,flex:2}}/>
                  <input placeholder="Stk." type="number" min="1" step="1" value={incForm.qty} onChange={e=>setIncForm(f=>({...f,qty:e.target.value}))} style={{...inp,flex:1,maxWidth:80}}/>
                </div>
                <textarea placeholder="Notiz (optional)" value={incForm.note} onChange={e=>setIncForm(f=>({...f,note:e.target.value}))} rows={2} style={{...inp,resize:"none"}}/>
                <input type="date" value={incForm.date} onChange={e=>setIncForm(f=>({...f,date:e.target.value}))} style={inp}/>
                {incErr&&<div style={{color:C.red,fontSize:13}}>{incErr}</div>}
                {incForm.price&&incForm.qty&&!isNaN(parseFloat(incForm.price))&&(
                  <div style={{fontSize:13,color:C.green,fontStyle:"italic"}}>Gesamt: {(parseFloat(incForm.price)*parseInt(incForm.qty||1)).toFixed(2)} €</div>
                )}
                <button onClick={handleIncSave} style={{...mkBtn(C.green),padding:"12px",width:"100%"}}>Einnahme speichern</button>
              </div>
            </div>
            {data.incomes.length>0&&<InvoiceBuilder incomes={data.incomes} onInvoice={items=>setInvoiceItems(items)}/>}
            <div style={{fontSize:11,letterSpacing:3,textTransform:"uppercase",color:C.grey,marginBottom:12}}>Letzte Einnahmen</div>
            {data.incomes.length===0&&<div style={{color:C.grey,fontSize:14,fontStyle:"italic"}}>Noch keine Einnahmen.</div>}
            {data.incomes.slice(0,20).map(i=>(
              <div key={i.id} style={{display:"flex",alignItems:"center",background:"#fff",border:`1px solid ${C.purpleLt}33`,borderRadius:8,padding:"11px 14px",marginBottom:7,gap:10}}>
                <div style={{flex:1}}><div style={{fontSize:13}}>{i.description}</div><div style={{fontSize:11,color:C.grey,marginTop:2,textTransform:"uppercase",letterSpacing:1}}>{formatDate(i.date+"T00:00:00")} · {i.art} · {i.qty} Stk.</div>{i.note&&<div style={{fontSize:12,color:"#bbb",fontStyle:"italic",marginTop:2}}>{i.note}</div>}</div>
                <div style={{fontSize:15,color:C.green,minWidth:82,textAlign:"right",fontWeight:"bold"}}>{(i.price*i.qty).toFixed(2)} €</div>
                <button onClick={()=>deleteIncome(i.id)} style={{background:"none",border:"none",cursor:"pointer",color:C.purpleLt,fontSize:20,padding:"0 4px",lineHeight:1}}>×</button>
              </div>
            ))}
          </div>
        )}

        {/* ══ KALENDER ══ */}
        {tab==="kalender"&&<CalendarTab events={data.events||[]} setData={setData}/>}

        {/* ══ ÜBERSICHT ══ */}
        {tab==="uebersicht"&&(
          <div style={{paddingTop:24,paddingBottom:48}}>
            <div style={{fontSize:12,color:C.grey,fontStyle:"italic",marginBottom:18}}>Klicke auf einen Monat, um die Details aufzuklappen.</div>
            {allKeys.length===0&&<div style={{color:C.grey,fontSize:14,fontStyle:"italic"}}>Noch keine Daten vorhanden.</div>}
            {allKeys.map(key=>(
              <MonthCard key={key} monthKey={key}
                sessions={sessionsByMonth[key]||[]}
                expenses={expByMonth[key]||[]}
                incomes={incByMonth[key]||[]}
              />
            ))}
          </div>
        )}
      </div>
    </div>
  );
}
